from flask import Flask, request, jsonify
import json
from datetime import datetime

app = Flask(__name__)

# In-memory storage for students
students = {}

# In-memory storage for attendance records
attendance_records = {}

@app.route('/api/students', methods=['GET'])
def get_students():
    """Get all students."""
    return jsonify(students)

@app.route('/api/students/<student_id>', methods=['GET'])
def get_student(student_id):
    """Get a specific student by ID."""
    if student_id in students:
        return jsonify(students[student_id])
    return jsonify({"error": "Student not found"}), 404

@app.route('/api/students', methods=['POST'])
def add_student():
    """Add a new student."""
    data = request.get_json()

    if not data or 'name' not in data:
        return jsonify({"error": "Student name is required"}), 400

    student_id = data.get('id')
    if not student_id:
        student_id = len(students) + 1

    if student_id in students:
        return jsonify({"error": "Student already exists"}), 400

    students[student_id] = {
        "id": student_id,
        "name": data['name'],
        "email": data.get('email', '')
    }

    return jsonify(students[student_id]), 201

@app.route('/api/attendance/<student_id>', methods=['POST'])
def mark_attendance(student_id):
    """Mark attendance for a student."""
    data = request.get_json()

    # Validate student exists
    if student_id not in students:
        return jsonify({"error": "Student not found"}), 404

    # Validate required fields
    if not data or 'date' not in data:
        return jsonify({"error": "Date is required"}), 400

    # Validate date format (YYYY-MM-DD)
    date = data['date']
    try:
        date_obj = datetime.strptime(date, '%Y-%m-%d')
    except ValueError:
        return jsonify({"error": "Invalid date format. Use YYYY-MM-DD"}), 400

    # Check for duplicate attendance
    if student_id in attendance_records and date in attendance_records[student_id]:
        return jsonify({"error": "Attendance already recorded for this date"}), 400

    # Record attendance
    attendance_records[student_id] = attendance_records.get(student_id, {})
    attendance_records[student_id][date] = data.get('status', 'present')

    return jsonify({
        "student_id": student_id,
        "date": date,
        "status": data.get('status', 'present'),
        "message": "Attendance recorded successfully"
    }), 201

@app.route('/api/attendance/<student_id>', methods=['GET'])
def get_attendance(student_id):
    """Get attendance records for a student."""
    if student_id not in students:
        return jsonify({"error": "Student not found"}), 404

    return jsonify(attendance_records.get(student_id, {}))

@app.route('/api/attendance', methods=['GET'])
def get_all_attendance():
    """Get all attendance records."""
    return jsonify(attendance_records)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)
